  if (!o.deckY) for (let it = 0; it < 3; it++) Y = Y.map((y, i) => Math.max(bwDeckY(P[i], hw, 0.12), (Y[Math.max(0, i - 1)] + y * 2 + Y[Math.min(Y.length - 1, i + 1)]) / 4));
