    s.p[0] += (s.v[0] + Math.sin(s.ph + s.life * 7) * 0.4) * dt; s.p[1] += s.v[1] * dt; s.p[2] += (s.v[2] + Math.cos(s.ph + s.life * 6) * 0.4) * dt;
