    mm.mat(MAT.PLAIN, [0.55, 0.38, 0.2]); for (let i = 0; i < 5; i++) { const x = -0.65 + i * 0.32; mm.push().T(x, 1.28, 0); mm.ball(0, -0.3, 0, 0.045, 0.3, 0.025, 6, 4); mm.pop(); }
