  def('jump', 'foot', 1, 0.3, (S, c, o, t, v) => { S.voc(o, t, { f0: 150, f1: 185, d: 0.12, a: 0.015, v: 0.14 * v, form: [[600, 5, 1], [1000, 6, 0.5], [2500, 8, 0.2]], breath: 0.4 }); S.nb(o, t, { f: 2800, q: 0.4, a: 0.03, d: 0.14, v: 0.1 * v, hp: 1200 }); }, { gap: 0.2 });
