  G.nSquare = 0; G.nMarket = 0; G.nInn = 0; G.nearSquare = 99; G.nearMarket = 99; G.nearInn = 99; G.millOn = false; G.grindOn = false; G.pHunter = null; G.pBarn = null; G.pFarm = null;
