    for (const [k, w] of [['pine', 1], ['birch', 1], ['oak', 3]]) for (const t of V[k] || []) { const i = Math.floor((t[0] + HALF) / CELL), j = Math.floor((t[2] + HALF) / CELL); if (i >= 0 && j >= 0 && i < NG && j < NG) forestGrid[j * NG + i] = Math.min(255, forestGrid[j * NG + i] + w); }
