    d[o + 4] = s.col[0]; d[o + 5] = s.col[1]; d[o + 6] = s.col[2]; d[o + 7] = smoke ? (1 - k) * 0.5 : 3.2 * (1 - k); d[o + 8] = s.seed * 6; d[o + 9] = s.kind; d[o + 10] = 1; d[o + 11] = s.seed;
